SELECT 
  FROM biz22_fee_charge_calc
 WHERE biz22_cont_corp_id = #{contCorpId}
   AND biz22_charge_date  = #{chargeDate}
 ORDER BY biz22_term_start_date

SELECT t.biz11_cont_corp_id AS cont_corp_id , t.biz11_company_id AS company_id , t.biz11_fee_calc_start_date AS fee_calc_start_date , t.biz11_fee_calc_close_date AS fee_calc_close_date , f_get_datedif(biz11_fee_calc_start_date, biz11_fee_calc_close_date, 'D') + 1 AS calc_days FROM ( SELECT biz11.* , biz10_company_id as biz11_company_id , ( SELECT MIN(biz11_cont_date) FROM biz11_cont_history WHERE biz11_cont_corp_id = biz10_cont_corp_id ) as biz11_first_cont_date , CASE WHEN COALESCE(biz12_fee_charge_type,'1') = '1' THEN #{startDate}::date ELSE CAST(to_date(to_char(#{closeDate}::date,'yyyy')|| to_char(biz11_start_date,'mmdd'),'yyyymmdd') - INTERVAL '1year' as DATE) END as biz11_fee_calc_start_date , CASE WHEN COALESCE(biz12_fee_charge_type,'1') = '1' THEN #{closeDate}::date ELSE CAST(to_date(to_char(#{closeDate}::date,'yyyy') ||to_char(biz11_start_date,'mmdd'),'yyyymmdd') - INTERVAL '1day' as DATE) END as biz11_fee_calc_close_date FROM biz10_cont_corp INNER JOIN ( SELECT * FROM biz11_cont_history LEFT OUTER JOIN biz12_fee_info ON biz12_cont_history_id = biz11_cont_history_id WHERE (biz11_cont_corp_id, biz11_reg_date) IN ( SELECT biz11_cont_corp_id, MAX(biz11_reg_date) FROM biz11_cont_history WHERE #{startDate}::date <= biz11_close_date AND #{closeDate}::date >= biz11_start_date GROUP BY biz11_cont_corp_id ) ) biz11 ON biz11_cont_corp_id = biz10_cont_corp_id WHERE biz10_company_id = #{companyId} AND NOT EXISTS ( SELECT 1 FROM biz20_fee_charge WHERE biz20_charge_date = #{closeDate}::date AND biz20_cont_corp_id = biz10_cont_corp_id AND biz20_fix_yn = 'true' ) /* 청구자료가 확정된 경우 처리대상에서 제외*/
AND biz10_cont_corp_id = #{contCorpId}
AND biz11_cont_status_cd IN ('1','2','3') /* (1:계약/2:재계약/3:계약연장) */ AND ( ( /* (1:분기별 청구) */ COALESCE(biz12_fee_charge_type,'1') = '1' AND biz11_start_date <= #{closeDate}::date AND biz11_close_date >= #{startDate}::date ) OR ( /* (2:연별 청구-1년 후취) */ COALESCE(biz12_fee_charge_type,'1') = '2' AND biz11_start_date <= #{closeDate}::date AND biz11_close_date >= CAST(#{closeDate}::date + INTERVAL '-1year + 1day' as DATE) AND f_get_last_day(cast(f_get_quarter_date(to_date(to_char(#{closeDate}::date,'yyyy')|| to_char(biz11_start_date,'mmdd'),'yyyymmdd') ,'1') + interval '3month' as date)) = #{closeDate}::date ) ) ) t ORDER BY biz11_first_cont_date, biz11_cont_corp_nm

SELECT biz20_fee_charge_id AS fee_charge_id
     , biz20_fix_yn        AS fix_yn
     , CAST(NULL AS varchar) AS manage_type
  FROM biz20_fee_charge
 WHERE biz20_company_id   = #{companyId}
   AND biz20_charge_date  = #{chargeDate}
   AND biz20_cont_corp_id = #{contCorpId}
   AND biz20_corp_id      = #{corpId}

SELECT sum(biz21_occ_fee)
  FROM biz21_fee_charge_dtl
 WHERE biz21_fee_charge_id IN ( SELECT biz20_fee_charge_id
                                  FROM biz20_fee_charge
                                 WHERE biz20_charge_date  = #{chargeDate}
                                   AND biz20_cont_corp_id = #{contCorpId}
                                   AND biz20_corp_id      = #{corpId} )
   AND biz21_occ_date BETWEEN #{startDate} AND #{closeDate}

