UPDATE biz22_fee_charge_calc
   SET biz22_term_days              = f_get_datedif(#{t.termStartDate}, #{t.termCloseDate}, 'D') + 1
     , biz22_min_fee_yn             = #{t.minFeeYn}
     , biz22_manage_min_fee         = #{t.manageMinFee}
     , biz22_manage_term_min_fee    = #{t.manageTermMinFee}
     , biz22_manage_term_occ_fee    = #{t.manageTermOccFee}
     , biz22_manage_term_with_fee   = #{t.manageTermWithFee}
     , biz22_manage_term_charge_fee = #{t.manageTermChargeFee}
     , biz22_adv_min_fee            = #{t.advMinFee}
     , biz22_adv_term_min_fee       = #{t.advTermMinFee}
     , biz22_adv_term_occ_fee       = #{t.advTermOccFee}
     , biz22_adv_term_with_fee      = #{t.advTermWithFee}
     , biz22_adv_term_charge_fee    = #{t.advTermChargeFee}
     , biz22_discr_min_fee          = #{t.discrMinFee}
     , biz22_discr_term_min_fee     = #{t.discrTermMinFee}
     , biz22_discr_term_occ_fee     = #{t.discrTermOccFee}
     , biz22_discr_term_with_fee    = #{t.discrTermWithFee}
     , biz22_discr_term_charge_fee  = #{t.discrTermChargeFee}
     , biz22_with_yn                = #{t.withYn}
     , biz22_with_fee               = #{t.withFee}
     , biz22_with_term_with_fee     = #{t.withTermWithFee}
     , biz22_with_term_occ_fee      = #{t.withTermOccFee}
     , biz22_with_term_charge_fee   = #{t.withTermChargeFee}
 WHERE biz22_fee_charge_calc_id = #{t.feeChargeCalcId}

mapper.select:
SELECT MIN(biz20_occ_start_date ) as occ_start_date , MIN(biz20_occ_close_date ) as occ_close_date , SUM(biz20_occ_days ) as occ_days , SUM(biz20_occ_fee ) as occ_fee , MIN(biz20_min_start_date ) as min_start_date , MIN(biz20_min_close_date ) as min_close_date , SUM(biz20_min_days ) as min_days , SUM(biz20_min_fee ) as min_fee , MIN(biz20_with_start_date) as with_start_date , MIN(biz20_with_close_date) as with_close_date , SUM(biz20_with_days ) as with_days , SUM(biz20_with_fee ) as with_fee , SUM(biz20_charge_fee ) as charge_fee , CASE WHEN #{manageType,jdbcType=VARCHAR} != '1' THEN SUM(biz20_charge_fee) * 0.1 ELSE 0 END as tax , CASE WHEN SUM(biz20_charge_fee) != 0 THEN 'true' ELSE 'false' END as target_yn FROM (
/***************** 병행정보 ************************************/ SELECT '9999-12-31'::date as biz20_occ_start_date , '9999-12-31'::date as biz20_occ_close_date , 0 as biz20_occ_days , 0 as biz20_occ_fee , '9999-12-31'::date as biz20_min_start_date , '9999-12-31'::date as biz20_min_close_date , 0 as biz20_min_days , 0 as biz20_min_fee , MIN(biz22_term_start_date) as biz20_with_start_date , MAX(biz22_term_close_date) as biz20_with_close_date , SUM(biz22_term_days) as biz20_with_days , SUM(biz22_with_term_charge_fee) as biz20_with_fee , 0 as biz20_charge_fee FROM biz22_fee_charge_calc WHERE biz22_cont_corp_id = #{contCorpId} AND biz22_charge_date = #{chargeDate} AND biz22_with_term_with_fee != 0
/***************** 운용 ************************************/ UNION SELECT MIN(biz22_term_start_date) as biz20_occ_start_date , MAX(biz22_term_close_date) as biz20_occ_close_date , SUM(biz22_term_days) as biz20_occ_days , SUM(biz22_manage_term_occ_fee) as biz20_occ_fee , '9999-12-31' as biz20_min_start_date , '9999-12-31' as biz20_min_close_date , 0 as biz20_min_days , 0 as biz20_min_fee , '9999-12-31' as biz20_with_start_date , '9999-12-31' as biz20_with_close_date , 0 as biz20_with_days , 0 as biz20_with_fee , 0 as biz20_charge_fee FROM biz22_fee_charge_calc WHERE biz22_cont_corp_id = #{contCorpId} AND biz22_charge_date = #{chargeDate} AND '1' = #{manageType,jdbcType=VARCHAR} AND biz22_manage_term_occ_fee != 0 UNION SELECT '9999-12-31' as biz20_occ_start_date , '9999-12-31' as biz20_occ_close_date , 0 as biz20_occ_days , 0 as biz20_occ_fee , MIN(biz22_term_start_date) as biz20_min_start_date , MAX(biz22_term_close_date) as biz20_min_close_date , SUM(biz22_term_days) as biz20_min_days , SUM(biz22_manage_term_min_fee) as biz20_min_fee , '9999-12-31' as biz20_with_start_date , '9999-12-31' as biz20_with_close_date , 0 as biz20_with_days , 0 as biz20_with_fee , 0 as biz20_charge_fee FROM biz22_fee_charge_calc WHERE biz22_cont_corp_id = #{contCorpId} AND biz22_charge_date = #{chargeDate} AND '1' = #{manageType,jdbcType=VARCHAR} AND biz22_manage_term_min_fee != 0 UNION SELECT '9999-12-31' as biz20_occ_start_date , '9999-12-31' as biz20_occ_close_date , 0 as biz20_occ_days , 0 as biz20_occ_fee , '9999-12-31' as biz20_min_start_date , '9999-12-31' as biz20_min_close_date , 0 as biz20_min_days , 0 as biz20_min_fee , '9999-12-31' as biz20_with_start_date , '9999-12-31' as biz20_with_close_date , 0 as biz20_with_days , 0 as biz20_with_fee , SUM(biz22_manage_term_charge_fee) as biz20_charge_fee FROM biz22_fee_charge_calc WHERE biz22_cont_corp_id = #{contCorpId} AND biz22_charge_date = #{chargeDate} AND '1' = #{manageType,jdbcType=VARCHAR} AND biz22_manage_term_charge_fee != 0
/***************** 자문 ************************************/ UNION SELECT MIN(biz22_term_start_date) as biz20_occ_start_date , MAX(biz22_term_close_date) as biz20_occ_close_date , SUM(biz22_term_days) as biz20_occ_days , SUM(biz22_adv_term_occ_fee) as biz20_occ_fee , '9999-12-31' as biz20_min_start_date , '9999-12-31' as biz20_min_close_date , 0 as biz20_min_days , 0 as biz20_min_fee , '9999-12-31' as biz20_with_start_date , '9999-12-31' as biz20_with_close_date , 0 as biz20_with_days , 0 as biz20_with_fee , 0 as biz20_charge_fee FROM biz22_fee_charge_calc WHERE biz22_cont_corp_id = #{contCorpId} AND biz22_charge_date = #{chargeDate} AND '2' = #{manageType,jdbcType=VARCHAR} AND biz22_adv_term_occ_fee != 0 UNION SELECT '9999-12-31' as biz20_occ_start_date , '9999-12-31' as biz20_occ_close_date , 0 as biz20_occ_days , 0 as biz20_occ_fee , MIN(biz22_term_start_date) as biz20_min_start_date , MAX(biz22_term_close_date) as biz20_min_close_date , SUM(biz22_term_days) as biz20_min_days , SUM(biz22_adv_term_min_fee) as biz20_min_fee , '9999-12-31' as biz20_with_start_date , '9999-12-31' as biz20_with_close_date , 0 as biz20_with_days , 0 as biz20_with_fee , 0 as biz20_charge_fee FROM biz22_fee_charge_calc WHERE biz22_cont_corp_id = #{contCorpId} AND biz22_charge_date = #{chargeDate} AND '2' = #{manageType,jdbcType=VARCHAR} AND biz22_adv_term_min_fee != 0 UNION SELECT '9999-12-31' as biz20_occ_start_date , '9999-12-31' as biz20_occ_close_date , 0 as biz20_occ_days , 0 as biz20_occ_fee , '9999-12-31' as biz20_min_start_date , '9999-12-31' as biz20_min_close_date , 0 as biz20_min_days , 0 as biz20_min_fee , '9999-12-31' as biz20_with_start_date , '9999-12-31' as biz20_with_close_date , 0 as biz20_with_days , 0 as biz20_with_fee , SUM(biz22_adv_term_charge_fee) as biz20_charge_fee FROM biz22_fee_charge_calc WHERE biz22_cont_corp_id = #{contCorpId} AND biz22_charge_date = #{chargeDate} AND '2' = #{manageType,jdbcType=VARCHAR} AND biz22_adv_term_charge_fee != 0
/***************** 일임 ************************************/ UNION SELECT MIN(biz22_term_start_date) as biz20_occ_start_date , MAX(biz22_term_close_date) as biz20_occ_close_date , SUM(biz22_term_days) as biz20_occ_days , SUM(biz22_discr_term_occ_fee) as biz20_occ_fee , '9999-12-31' as biz20_min_start_date , '9999-12-31' as biz20_min_close_date , 0 as biz20_min_days , 0 as biz20_min_fee , '9999-12-31' as biz20_with_start_date , '9999-12-31' as biz20_with_close_date , 0 as biz20_with_days , 0 as biz20_with_fee , 0 as biz20_charge_fee FROM biz22_fee_charge_calc WHERE biz22_cont_corp_id = #{contCorpId} AND biz22_charge_date = #{chargeDate} AND '3' = #{manageType,jdbcType=VARCHAR} AND biz22_discr_term_occ_fee != 0 UNION SELECT '9999-12-31' as biz20_occ_start_date , '9999-12-31' as biz20_occ_close_date , 0 as biz20_occ_days , 0 as biz20_occ_fee , MIN(biz22_term_start_date) as biz20_min_start_date , MAX(biz22_term_close_date) as biz20_min_close_date , SUM(biz22_term_days) as biz20_min_days , SUM(biz22_discr_term_min_fee) as biz20_min_fee , '9999-12-31' as biz20_with_start_date , '9999-12-31' as biz20_with_close_date , 0 as biz20_with_days , 0 as biz20_with_fee , 0 as biz20_charge_fee FROM biz22_fee_charge_calc WHERE biz22_cont_corp_id = #{contCorpId} AND biz22_charge_date = #{chargeDate} AND '3' = #{manageType,jdbcType=VARCHAR} AND biz22_discr_term_min_fee != 0 UNION SELECT '9999-12-31' as biz20_occ_start_date , '9999-12-31' as biz20_occ_close_date , 0 as biz20_occ_days , 0 as biz20_occ_fee , '9999-12-31' as biz20_min_start_date , '9999-12-31' as biz20_min_close_date , 0 as biz20_min_days , 0 as biz20_min_fee , '9999-12-31' as biz20_with_start_date , '9999-12-31' as biz20_with_close_date , 0 as biz20_with_days , 0 as biz20_with_fee , SUM(biz22_discr_term_charge_fee) as biz20_charge_fee FROM biz22_fee_charge_calc WHERE biz22_cont_corp_id = #{contCorpId} AND biz22_charge_date = #{chargeDate} AND '3' = #{manageType,jdbcType=VARCHAR} AND biz22_discr_term_charge_fee != 0
) t

mapper.update:
UPDATE biz20_fee_charge
   SET biz20_calc_start_date = #{calcStartDate}
     , biz20_calc_close_date = #{calcCloseDate}
     , biz20_calc_days       = #{calcDays}
     , biz20_occ_start_date  = #{f.occStartDate}
     , biz20_occ_close_date  = #{f.occCloseDate}
     , biz20_occ_days        = #{f.occDays}
     , biz20_occ_fee         = #{f.occFee}
     , biz20_min_start_date  = #{f.minStartDate}
     , biz20_min_close_date  = #{f.minCloseDate}
     , biz20_min_days        = #{f.minDays}
     , biz20_min_fee         = #{f.minFee}
     , biz20_with_start_date = #{f.withStartDate}
     , biz20_with_close_date = #{f.withCloseDate}
     , biz20_with_days       = #{f.withDays}
     , biz20_with_fee        = #{f.withFee}
     , biz20_target_yn       = #{f.targetYn}
     , biz20_charge_fee      = #{f.chargeFee}
     , biz20_tax             = #{f.tax}
 WHERE biz20_fee_charge_id = #{feeChargeId}

